import {
    Entity,
    PrimaryGeneratedColumn,
    Column,
    CreateDateColumn,
    Unique,
} from 'typeorm';

// Lesson audio generated by POST /api/ai/tts. One row per (voice, model, settings, text);
// a repeat request returns audio_url instead of calling the provider again.
@Entity('tts_audios')
@Unique('UQ_tts_audios_text_hash', ['text_hash'])
export class TtsAudio {
    @PrimaryGeneratedColumn({ primaryKeyConstraintName: 'PK_tts_audios' })
    id!: number;

    // sha256 of provider settings + text
    @Column({ type: 'varchar', length: 64 })
    text_hash!: string;

    @Column({ type: 'varchar', length: 50 })
    provider!: string;

    @Column({ type: 'varchar', length: 100 })
    voice_id!: string;

    @Column({ type: 'varchar', length: 100 })
    model_id!: string;

    @Column({ type: 'numeric', precision: 4, scale: 2, default: 1 })
    speed!: string;

    @Column({ type: 'text' })
    text!: string;

    @Column({ type: 'varchar', length: 500 })
    storage_key!: string;

    @Column({ type: 'text' })
    audio_url!: string;

    @Column({ type: 'integer', nullable: true })
    file_size_bytes?: number | null;

    @Column({ type: 'integer', nullable: true })
    created_by?: number | null;

    @CreateDateColumn()
    created_at!: Date;
}
